// "Ủng hộ tác giả" — a banner with the reason on the left and the QR + bank details on the right.
import { h, icon, copyText } from '../lib/dom.js';
import { openModal } from '../lib/modal.js';
import { ok } from '../lib/toast.js';
import { t, localeTag } from '../i18n/index.js';

// Bank transfer details are real-world payment data, not UI copy — same in every language (owner's
// rule for README.en.md applies here too: same bank details, same transfer note).
export const BANK = { bank: 'TPBank', holder: 'TA NGOC TU', number: '0066 6777 888', numberRaw: '00666777888', note: 'Moi cafe Auto Beep Toptop', qr: 'data:image/png;base64,' };

export function openDonate({ captcha } = {}) {
  const kv = (label, value, copyValue) => h('div', { class: 'kv' }, h('span', {}, label), h('b', {}, value),
    copyValue ? h('button', { onClick: async () => { await copyText(copyValue); ok(t('donate.copied'), copyValue); } }, t('donate.copy')) : null);
  const qty = captcha && captcha.author && captcha.author.quantity != null ? Number(captcha.author.quantity) : null;
  const body = h('div', { class: 'donate' },
    h('div', { class: 'why' },
      h('h3', {}, t('donate.why.title')),
      h('p', {}, t('donate.why.p1a'), h('b', {}, t('donate.why.p1b')), t('donate.why.p1c')),
      h('ul', {},
        h('li', {}, t('donate.why.li1')),
        h('li', {}, t('donate.why.li2'))),
      qty != null ? h('div', { class: `callout ${qty > 0 ? '' : 'warn'}` }, t('donate.captcha.line', {
        pkg: captcha.author.packageName ? t('donate.captcha.package', { name: captcha.author.packageName }) : '',
        qty: qty.toLocaleString(localeTag()),
        exp: captcha.author.dateEnd ? t('donate.captcha.expires', { date: new Date(captcha.author.dateEnd).toLocaleDateString(localeTag()) }) : '',
        bad: captcha.author.ok ? '' : t('donate.captcha.bad'),
      })) : null,
      h('p', { class: 'hint', style: { marginTop: '10px' } }, t('donate.why.hint')),
    ),
    h('div', {},
      h('div', { class: 'qr-card' }, h('img', { src: BANK.qr, alt: 'VietQR TPBank' })),
      h('div', { class: 'bank' },
        kv(t('donate.bank.bank'), BANK.bank),
        kv(t('donate.bank.holder'), BANK.holder, BANK.holder),
        kv(t('donate.bank.number'), BANK.number, BANK.numberRaw),
        kv(t('donate.bank.note'), BANK.note, BANK.note)),
    ),
  );
  return openModal({ title: t('donate.modalTitle'), body, size: 'lg', foot: [h('span', { class: 'spacer' }), h('span', { class: 'hint' }, t('donate.thanks'))] });
}

export function donateButton(onClick) {
  return h('button', { class: 'donate-btn', onClick }, icon('heart'), h('span', {}, h('b', {}, t('donate.buttonLabel')), h('small', {}, t('donate.buttonSub'))));
}
